python -c "
import os
from pathlib import Path
import re

print('=' * 60)
print('Elysia Bot 配置检查')
print('=' * 60)

errors = []
warnings = []

# 1. 检查 .env.prod
print('\n【1. 环境配置文件】')
env_file = Path('.env.prod')
if env_file.exists():
    print('✅ .env.prod 存在')

    # 读取配置
    with open(env_file) as f:
        content = f.read()

    # 检查关键配置
    if 'QQ_BOTS' in content:
        print('✅ QQ_BOTS 配置存在')

        # 尝试解析 JSON
        try:
            import json
            match = re.search(r'QQ_BOTS=\"([^\"]+)\"', content)
            if match:
                qq_bots = json.loads(match.group(1))
                if isinstance(qq_bots, list) and len(qq_bots) > 0:
                    bot = qq_bots[0]
                    if bot.get('id') and bot.get('id') != 'xxx':
                        print(f'   Bot ID: {bot[\"id\"]}')
                    else:
                        warnings.append('QQ Bot ID 未配置')
                    if bot.get('token') and bot.get('token') != 'xxx':
                        print('   Token: 已配置')
                    else:
                        errors.append('QQ Bot Token 未配置')
                    if bot.get('secret') and bot.get('secret') != 'xxx':
                        print('   Secret: 已配置')
                    else:
                        errors.append('QQ Bot Secret 未配置')
        except:
            warnings.append('无法解析 QQ_BOTS 配置')
    else:
        errors.append('QQ_BOTS 配置缺失')
else:
    errors.append('.env.prod 文件不存在，请从 example.env.prod 复制')

# 2. 检查 api_config.py
print('\n【2. API 配置文件】')
api_config_file = Path('src/configs/api_config.py')
api_config_example = Path('src/configs/api_config_example.py')

if api_config_file.exists():
    print('✅ api_config.py 存在')

    with open(api_config_file) as f:
        content = f.read()

    # 检查配置项
    if 'app_id' in content and '<KEY>' not in content:
        print('✅ app_id 已配置')
    else:
        warnings.append('app_id 可能未配置')

    if 'smms_token' in content or 'ju_he_token' in content:
        print('✅ 图床 Token 已配置')
    else:
        warnings.append('图床 Token 未配置（可选）')

    if 'v3key' in content or 'deepseek_key' in content:
        print('✅ AI API Key 已配置')
    else:
        warnings.append('AI API Key 未配置（如需使用 AI 功能请配置）')

    if 'admin_password' in content:
        match = re.search(r'admin_password\s*=\s*[\"\']([^\"\']+)[\"\']', content)
        if match:
            print(f'✅ 管理员密码已配置: {match.group(1)}')
else:
    if api_config_example.exists():
        errors.append('api_config.py 不存在，请从 api_config_example.py 复制并配置')
    else:
        warnings.append('api_config.py 不存在')

# 3. 检查路径配置
print('\n【3. 路径配置】')
path_config = Path('src/configs/path_config.py')
if path_config.exists():
    print('✅ path_config.py 存在')
else:
    warnings.append('path_config.py 不存在')

# 4. 检查依赖文件
print('\n【4. 依赖文件】')
req_file = Path('requirements_Elysia.txt')
if req_file.exists():
    print('✅ requirements_Elysia.txt 存在')
else:
    errors.append('requirements_Elysia.txt 不存在')

pyproject = Path('pyproject.toml')
if pyproject.exists():
    print('✅ pyproject.toml 存在')
else:
    errors.append('pyproject.toml 不存在')

# 5. 检查 Node.js 依赖
print('\n【5. Node.js 依赖】')
package_json = Path('package.json')
node_modules = Path('node_modules')
if package_json.exists():
    print('✅ package.json 存在')
    if node_modules.exists():
        print('✅ node_modules 存在（已安装）')
    else:
        warnings.append('node_modules 不存在，请运行: npm install')
else:
    warnings.append('package.json 不存在')

# 6. 检查数据库
print('\n【6. 数据库】')
db_file = Path('chat_bot.db')
if db_file.exists():
    size_mb = db_file.stat().st_size / 1024 / 1024
    print(f'✅ chat_bot.db 存在 ({size_mb:.2f} MB)')
else:
    warnings.append('chat_bot.db 不存在，首次启动会自动创建')

# 7. 检查关键目录
print('\n【7. 目录结构】')
dirs = ['src/plugins', 'src/configs', 'src/resources', 'src/clover_sqlite']
for d in dirs:
    if Path(d).exists():
        print(f'✅ {d} 存在')
    else:
        errors.append(f'{d} 不存在')

# 总结
print('\n' + '=' * 60)
print('检查结果')
print('=' * 60)

if not errors and not warnings:
    print('✅ 所有配置检查通过！可以启动机器人。')
elif errors:
    print(f'❌ 发现 {len(errors)} 个错误:')
    for err in errors:
        print(f'   - {err}')
    print('\n请修复以上错误后再启动。')

if warnings:
    print(f'\n⚠️  发现 {len(warnings)} 个警告:')
    for warn in warnings:
        print(f'   - {warn}')

print('=' * 60)
"
